<?php

namespace Database\Seeders;

use App\Models\HousingUnit;
use Illuminate\Database\Seeder;

/**
 * The 10 houses of the campus town. Each unit is linked to its assets by model_key
 * (front/public/assets/houses/<model_key>/) and positioned at the door interaction point.
 *
 * Positions come from front/public/assets/town/town.layout.json ("door"), generated by
 * map-src/CampusCove/build_town.py — regenerate both together if the town layout changes.
 */
class HousingUnitSeeder extends Seeder
{
    /** @var list<array{0:string,1:string,2:int,3:float,4:float,5:float,6:string}> key, offer, price, x, y, z, colour */
    private const HOUSES = [
        ['house_01', 'rent', 90, 9.023, 1.25, 27.771, '#E8E4DA'],     // Maple Cottage
        ['house_02', 'rent', 110, 23.623, 1.25, 17.163, '#78A0C4'],   // Bluebell Bungalow
        ['house_03', 'rent', 120, 29.2, 1.25, 0.0, '#E8C878'],        // Sunny Nook
        ['house_04', 'buy', 1800, 23.623, 1.25, -17.163, '#96C8AA'],  // Mint Villa
        ['house_05', 'buy', 2400, 9.023, 1.25, -27.771, '#9C4834'],   // Brick Townhouse
        ['house_06', 'rent', 160, -9.023, 1.25, -27.771, '#D69696'],  // Rose Cottage
        ['house_07', 'buy', 2800, -23.623, 1.25, -17.163, '#CE7858'], // Terracotta Casa
        ['house_08', 'buy', 3600, -29.2, 1.25, 0.0, '#F0F0EE'],       // Modern Cube
        ['house_09', 'buy', 3200, -23.623, 1.25, 17.163, '#3A3C48'],  // Neon Loft
        ['house_10', 'buy', 4000, -9.023, 1.25, 27.771, '#8A5A3A'],   // Forest Lodge
    ];

    public function run(): void
    {
        // Legacy MVP cubes (no model_key) are replaced by the houses; occupied ones are left alone.
        HousingUnit::query()->whereNull('model_key')->where('status', 'vacant')->delete();

        foreach (self::HOUSES as [$key, $offer, $price, $x, $y, $z, $color]) {
            $unit = HousingUnit::query()->firstOrNew(['model_key' => $key]);
            $unit->fill([
                'offer_type' => $offer,
                'price_coins' => $price,
                'rent_duration_hours' => 24,
                'pos_x' => $x,
                'pos_y' => $y,
                'pos_z' => $z,
                'size' => 2.5,
                'base_color_hex' => $color,
            ]);
            if (! $unit->exists) {
                $unit->status = 'vacant';
            }
            $unit->save();
        }
    }
}
